// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of http.ServeMux.
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	ServeHTTP(w http.ResponseWriter, r *http.Request)
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc("GET "+options.BaseURL+"/healthz", wrapper.GetHealthz)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/channel-blocks/{channel_id}", wrapper.UnblockChannel)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/channel-blocks/{channel_id}", wrapper.BlockChannel)
	m.HandleFunc("GET "+options.BaseURL+"/v1/config", wrapper.GetConfig)
	m.HandleFunc("POST "+options.BaseURL+"/v1/events", wrapper.PostEvents)
	m.HandleFunc("GET "+options.BaseURL+"/v1/feed", wrapper.GetFeed)
	m.HandleFunc("GET "+options.BaseURL+"/v1/languages", wrapper.ListLanguages)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/me", wrapper.DeleteMe)
	m.HandleFunc("GET "+options.BaseURL+"/v1/me", wrapper.GetMe)
	m.HandleFunc("PATCH "+options.BaseURL+"/v1/me", wrapper.UpdateMe)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/me/languages/{code}", wrapper.DeleteMyLanguage)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/me/languages/{code}", wrapper.PutMyLanguage)
	m.HandleFunc("GET "+options.BaseURL+"/v1/me/likes", wrapper.ListMyLikes)
	m.HandleFunc("GET "+options.BaseURL+"/v1/me/saves", wrapper.ListMySaves)
	m.HandleFunc("POST "+options.BaseURL+"/v1/sessions/anonymous", wrapper.CreateAnonymousSession)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/videos/{id}/hide", wrapper.HideVideo)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/videos/{id}/like", wrapper.UnlikeVideo)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/videos/{id}/like", wrapper.LikeVideo)
	m.HandleFunc("POST "+options.BaseURL+"/v1/videos/{id}/report", wrapper.ReportVideo)
	m.HandleFunc("DELETE "+options.BaseURL+"/v1/videos/{id}/save", wrapper.UnsaveVideo)
	m.HandleFunc("PUT "+options.BaseURL+"/v1/videos/{id}/save", wrapper.SaveVideo)

	return m
}

